-- Run only on isolated staging via SQL tooling. Entire transaction rolls back.
begin;
insert into auth.users(id,aud,role,email) values('90000000-0000-4000-8000-000000000001','authenticated','authenticated','acceptance-owner@example.invalid'),('90000000-0000-4000-8000-000000000002','authenticated','authenticated','acceptance-other@example.invalid');
