select set_config('request.jwt.claims','{"sub":"90000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('test.workspace',create_workspace_with_owner('Acceptance A','acceptance-a-20261009','["CRO"]','{US}','{beauty}')::text,true);
select set_config('request.jwt.claims','{"sub":"90000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select set_config('test.other_workspace',create_workspace_with_owner('Acceptance B','acceptance-b-20261009','[]','{CA}','{}')::text,true);
insert into accounts(id,workspace_id,domain,name) values('90000000-0000-4000-8000-000000000007',current_setting('test.other_workspace')::uuid,'other.example.invalid','Other synthetic account');
insert into contacts(workspace_id,account_id,email) values(current_setting('test.other_workspace')::uuid,'90000000-0000-4000-8000-000000000007','other@example.invalid');
insert into signals(workspace_id,account_id,signal_type,title,source_url,observed_at) values(current_setting('test.other_workspace')::uuid,'90000000-0000-4000-8000-000000000007','acceptance','Other synthetic signal','https://example.invalid',now());
