select pg_temp.expect_error(format('insert into durable_jobs(workspace_id,job_type,idempotency_key) values(%L,%L,%L)',current_setting('test.workspace'),'send_outreach','bad'),'check constraint','Send-like jobs denied');
select pg_temp.assert_ok((select outreach_id is not null from create_held_outreach_revision('90000000-0000-4000-8000-000000000003','90000000-0000-4000-8000-000000000004','Synthetic member','Synthetic held body','research','Synthetic reason','[{"id":"90000000-0000-4000-8000-000000000005"}]','[]','{"email":"buyer@example.invalid","emailVerified":true}','{"humanApprovalRequired":true,"autonomousSendEnabled":false}','acceptance-member-hash')),'Member prepares held draft');
select pg_temp.expect_error('select * from create_held_outreach_revision(''90000000-0000-4000-8000-000000000003'',''90000000-0000-4000-8000-000000000004'',''Synthetic'',''Synthetic'',''research'',''Synthetic'',''[]'',''[]'',''{}'',''{}'',''no-evidence'')','missing_evidence','No evidence blocks draft');
select pg_temp.expect_error('select * from create_held_outreach_revision(''90000000-0000-4000-8000-000000000003'',''90000000-0000-4000-8000-000000000004'',''Synthetic'',''Synthetic'',''research'',''Synthetic'',''[{"id":"90000000-0000-4000-8000-000000000005"}]'',''[]'',''{}'',''{"autonomousSendEnabled":true}'',''autonomous'')','autonomous_send_disabled','Autonomous draft flag rejected');
with changed as (update outreach_revisions set body='Tampered' where id=current_setting('test.revision')::uuid returning id) select pg_temp.assert_ok((select count(*)=0 from changed),'Revision mutation denied by RLS');
with changed as (update workspace_sales_config set outreach_rules='{}' where workspace_id=current_setting('test.workspace')::uuid returning workspace_id) select pg_temp.assert_ok((select count(*)=0 from changed),'Member cannot change policy');
reset role;
update workspace_members set role='viewer' where workspace_id=current_setting('test.workspace')::uuid and user_id='90000000-0000-4000-8000-000000000001';
