select pg_temp.expect_error(format('insert into accounts(workspace_id,domain,name) values(%L,%L,%L)',current_setting('test.workspace'),'viewer.example.invalid','Viewer write'),'row-level security','Viewer cannot create account');
select pg_temp.expect_error(format('select update_native_pipeline(%L,%L,2,%L,%L,null)',current_setting('test.workspace'),'90000000-0000-4000-8000-000000000003','ready','Viewer mutation'),'workspace operator required','Viewer cannot operate pipeline');
select pg_temp.expect_error(format('insert into durable_jobs(workspace_id,job_type,idempotency_key) values(%L,%L,%L)',current_setting('test.workspace'),'discovery','viewer-job'),'row-level security','Viewer cannot queue discovery');
