update workspace_members set role='admin' where workspace_id=current_setting('test.workspace')::uuid and user_id='90000000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.assert_ok(review_outreach_revision(current_setting('test.outreach')::uuid,current_setting('test.revision')::uuid,'approved') is not null,'Admin reviews exact revision');
select json_build_object('passed',count(*),'checks',json_agg(check_name order by check_name)) from acceptance_results;
rollback;
